const item = $input.first().json;
const b = item.body ?? item;
const base = String($env.CASTUO_BASE_URL || $env.CASTUO_API_URL || 'http://api:8000').replace(/\/+$/, '');
const apiKey = String($env.CASTUO_API_KEY || '').trim();
if (!apiKey) throw new Error('CASTUO_API_KEY requerido en entorno n8n');

const rawType = String(b.sensor_type || 'ph');
const sensor_type =
  rawType === 'temperatura' ? 'temperature' :
  rawType === 'humedad' ? 'humidity' :
  rawType === 'luz' ? 'light' :
  rawType;
const zone = String($env.CASTUO_ZONE_ID || 'zone_default');
const sensor_id = String(b.sensor_id || `sensor_${rawType}_${zone}`);
const value = Number(b.value);
if (Number.isNaN(value)) throw new Error('value numérico requerido');
const ts = b.timestamp || new Date().toISOString();
const location = String(b.location || 'default');
const unit =
  rawType === 'ph' ? 'pH' :
  rawType === 'temperatura' ? '°C' :
  rawType === 'humedad' ? '%' :
  rawType === 'ec' ? 'mS/cm' :
  'lux';

const reading = {
  sensor_id,
  sensor_type,
  value,
  timestamp: ts,
  location,
  unit,
  zone_id: zone,
};

const r1 = await fetch(`${base}/hydroponics-saas/sensor-readings`, {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'X-API-KEY': apiKey,
  },
  body: JSON.stringify(reading),
});
const t1 = await r1.text();
let castuo;
try {
  castuo = JSON.parse(t1);
} catch {
  castuo = { raw: t1 };
}

let mistral = { skipped: true, reason: 'MISTRAL_API_KEY vacío' };
const mk = String($env.MISTRAL_API_KEY || '').trim();
if (mk) {
  const summary = `Lectura: ${sensor_type}=${value} ${unit} zona=${zone} location=${location}. JSON bruto: ${JSON.stringify(b)}`;
  const r2 = await fetch('https://api.mistral.ai/v1/chat/completions', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${mk}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      model: 'mistral-small-latest',
      messages: [
        {
          role: 'system',
          content:
            'Eres agrónomo hidroponía UE. Respuesta breve, accionable, sin diagnóstico médico.',
        },
        { role: 'user', content: summary },
      ],
    }),
  });
  const t2 = await r2.text();
  try {
    mistral = JSON.parse(t2);
  } catch {
    mistral = { raw: t2, http_status: r2.status };
  }
}

return [
  {
    json: {
      hydro_request: reading,
      castuo_http_status: r1.status,
      castuo_response: castuo,
      mistral,
    },
  },
];
